  "message": "#21 [stage-0 11/11] RUN --mount=type=secret,id=render-env,target=/run/secrets/render-env [\"/bin/bash\",\"-c\",\". /opt/bex/load-env\\nset -e\\nnode --version\\nnpm --version\\nyarn --version\\npnpm --version\\nruby --version\\ncat \u003e qa342-probe.rb \u003c\u003c'QA342_RUBY_PROBE'\\nMARKER = \"QA342_58d23c_JS_TOOLS\"\\nrequire 'json'\\nrequire 'socket'\\nrequire 'open3'\\ndef tool(args)\\n started = Process.clock_gettime(Process::CLOCK_MONOTONIC)\\n out, err, status = Open3.capture3('timeout','60',*args)\\n { 'argv' =\u003e ['timeout','60']+args, 'exit' =\u003e status.exitstatus, 'stdout' =\u003e out, 'stderr' =\u003e err, 'error' =\u003e (status.exitstatus == 124 ? 'ETIMEDOUT' : nil), 'elapsed_ms' =\u003e ((Process.clock_gettime(Process::CLOCK_MONOTONIC)-started)*1000).round }\\nrescue Errno::ENOENT\\n { 'argv' =\u003e ['timeout','60']+args, 'exit' =\u003e nil, 'stdout' =\u003e '', 'stderr' =\u003e '', 'error' =\u003e 'observer_timeout_command_ENOENT' }\\nend\\ndef snapshot\\n { 'marker' =\u003e MARKER, 'runtime' =\u003e 'ruby', 'version' =\u003e RUBY_VERSION, 'tools' =\u003e {\\n 'node' =\u003e tool(['node','--version']), 'npm' =\u003e tool(['npm','--version']),\\n 'yarn' =\u003e tool(['yarn','--version']), 'pnpm' =\u003e tool(['pnpm','--version']),\\n 'ruby' =\u003e tool(['ruby','--version']), 'bundle' =\u003e tool(['bundle','--version']),\\n 'gem' =\u003e tool(['gem','--version']) } }\\nend\\nif ARGV.first == '--build'\\n value = snapshot\\n File.write('qa342-build.json', JSON.generate(value))\\n puts 'QA342_BUILD ' + JSON.generate(value)\\nelse\\n built = JSON.parse(File.read('qa342-build.json'))\\n current = snapshot\\n body = JSON.generate(current.merge('built' =\u003e built))\\n TCPServer.open('0.0.0.0', Integer(ENV.fetch('PORT','8080'))) do |server|\\n  loop do\\n   connection = server.accept\\n   begin\\n    while (line = connection.gets) \u0026\u0026 line != \"\\r\\n\"; end\\n    connection.write(\"HTTP/1.1 200 OK\\r\\nContent-Type: application/json\\r\\nContent-Length: #{body.bytesize}\\r\\nConnection: close\\r\\n\\r\\n\")\\n    connection.write(body)\\n   rescue IOError, SystemCallError\\n   ensure\\n    connection.close\\n   end\\n  end\\n end\\nend\\n\\nQA342_RUBY_PROBE\\nruby qa342-probe.rb --build\"]",
